mapper.select:
SELECT c.id, c.name, c.room, c.begin_date, c.end_date, c.master_id, c.subject, c.create_time, c.update_time, e.name AS masterName, ( CASE WHEN now() < c.begin_date THEN 'Not Started' WHEN now() > c.end_date THEN 'Completed' ELSE 'In Progress' END ) AS status FROM clazz AS c LEFT JOIN emp AS e ON c.master_id = e.id
c.name like concat('%', #{name}, '%')
AND c.begin_date >= #{begin}
AND c.end_date <= #{end}
ORDER BY c.begin_date DESC, c.end_date DESC, CONVERT( c.name USING gbk ) ASC, c.id ASC

mapper.update:
UPDATE clazz
name = #{name}, room = #{room}, begin_date = #{beginDate}, end_date = #{endDate}, master_id = #{masterId}, subject = #{subject}, update_time = #{updateTime},
WHERE id = #{id}
